{"content":"import { createFileRoute, Link } from "@tanstack/react-router";
import { Trash2 } from "lucide-react";
import { toast } from "sonner";
import { AVAILABILITY_LABEL, formatPrice } from "@/data/catalog";
import { COMPANY } from "@/data/company";
import { cartSubtotal, resolveLines, useStore } from "@/lib/store";

export const Route = createFileRoute("/cart")({
  head: () => ({
    meta: [
      { title: "Your Cart | Pickrel Brothers Wholesale Supply" },
      {
        name: "description",
        content:
          "Review your Pickrel Brothers order, adjust quantities, add a PO number and job notes, then check out or convert the cart to a quote request.",
      },
      { property: "og:title", content: "Your Cart | Pickrel Brothers Inc." },
      {
        property: "og:description",
        content: "Review quantities, add a PO number, and check out with Pickrel Brothers.",
      },
    ],
  }),
  component: CartPage,
});

function CartPage() {
  const { cart, setQty, removeFromCart, clearCart, cartNote, setCartNote, moveCartToQuote } = useStore();
  const lines = resolveLines(cart);
  const subtotal = cartSubtotal(lines);
  const hasCallForPricing = lines.some((l) => l.product.price === null);

  return (
    <div className="container-page py-10">
      <h1 className="font-display text-3xl font-bold uppercase text-navy">Your Cart</h1>

      {lines.length === 0 ? (
        <div className="mt-8 rounded-md border border-border bg-card p-12 text-center shadow-card">
          <p className="text-muted-foreground">Your cart is empty.</p>
          <Link
            to="/products"
            search={{ q: "", category: "", brand: "" }}
            className="mt-5 inline-block rounded-md bg-navy px-6 py-3 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted"
          >
            Browse the catalog
          </Link>
        </div>
      ) : (
        <div className="mt-8 grid gap-8 lg:grid-cols-[1fr_340px]">
          <section className="rounded-md border border-border bg-card shadow-card">
            <ul className="divide-y divide-border">
              {lines.map((l) => (
                <li key={l.slug} className="flex flex-wrap items-center gap-4 px-5 py-4">
                  <div className="min-w-[220px] flex-1">
                    <p className="text-xs font-bold uppercase text-sky">{l.product.manufacturer}</p>
                    <Link
                      to="/products/$slug"
                      params={{ slug: l.slug }}
                      className="text-sm font-semibold text-foreground hover:text-sky"
                    >
                      {l.product.name}
                    </Link>
                    <p className="font-mono text-xs text-muted-foreground">{l.product.mfrPartNumber}</p>
                    <p className="mt-1 text-xs text-muted-foreground">
                      {AVAILABILITY_LABEL[l.product.availability]}
                    </p>
                  </div>
                  <input
                    type="number"
                    min={1}
                    value={l.qty}
                    aria-label={`Quantity for ${l.product.name}`}
                    onChange={(e) => setQty(l.slug, Number(e.target.value))}
                    className="h-10 w-20 rounded-md border border-input bg-card px-2 text-sm"
                  />
                  <span className="w-24 text-right text-sm text-muted-foreground">
                    {formatPrice(l.product.price)}
                  </span>
                  <span className="w-28 text-right text-sm font-semibold text-foreground">
                    {l.extended === null ? "Call" : formatPrice(l.extended)}
                  </span>
                  <button
                    type="button"
                    onClick={() => removeFromCart(l.slug)}
                    aria-label={`Remove ${l.product.name}`}
                    className="rounded p-2 text-muted-foreground hover:text-destructive"
                  >
                    <Trash2 className="h-4 w-4" aria-hidden />
                  </button>
                </li>
              ))}
            </ul>

            <div className="border-t border-border px-5 py-4">
              <label className="block text-sm font-semibold text-navy">
                Job name / order notes
                <textarea
                  value={cartNote}
                  onChange={(e) => setCartNote(e.target.value)}
                  rows={3}
                  placeholder="Job name, will-call vs delivery, special instructions."
                  className="mt-1 block w-full rounded-md border border-input bg-card px-3 py-2 text-sm text-foreground"
                />
              </label>
              <div className="mt-3 flex flex-wrap gap-3">
                <button
                  type="button"
                  onClick={() => {
                    clearCart();
                    toast.success("Cart cleared");
                  }}
                  className="text-sm font-semibold text-muted-foreground hover:text-destructive"
                >
                  Clear cart
                </button>
                <button
                  type="button"
                  onClick={() => {
                    moveCartToQuote();
                    toast.success("Items copied to your quote list");
                  }}
                  className="text-sm font-semibold text-sky hover:underline"
                >
                  Copy to quote list
                </button>
              </div>
            </div>
          </section>

          <aside className="h-fit rounded-md border border-border bg-card p-6 shadow-card">
            <h2 className="font-display text-lg font-bold uppercase text-navy">Order summary</h2>
            <dl className="mt-4 space-y-2 text-sm">
              <div className="flex justify-between">
                <dt className="text-muted-foreground">Subtotal</dt>
                <dd className="font-semibold text-foreground">{formatPrice(subtotal)}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-muted-foreground">Freight / will-call</dt>
                <dd className="text-muted-foreground">Quoted at order</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-muted-foreground">Tax</dt>
                <dd className="text-muted-foreground">Per account exemption</dd>
              </div>
            </dl>
            {hasCallForPricing && (
              <p className="mt-4 rounded-md bg-sky-soft p-3 text-xs text-navy">
                Some items are priced by quotation. Our team will confirm pricing before the order ships.
              </p>
            )}
            <Link
              to="/checkout"
              className="mt-5 block rounded-md bg-navy px-6 py-3 text-center font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted"
            >
              Proceed to checkout
            </Link>
            <Link
              to="/quote"
              className="mt-3 block rounded-md border-2 border-navy px-6 py-2.5 text-center text-sm font-semibold text-navy hover:bg-secondary"
            >
              Request a quote instead
            </Link>
            <p className="mt-4 text-center text-xs text-muted-foreground">
              Questions? Call{" "}
              <a href={COMPANY.phoneHref} className="font-semibold text-sky">
                {COMPANY.phone}
              </a>
            </p>
          </aside>
        </div>
      )}
    </div>
  );
}
